class Dog:
    def __init__(self, name):
        self.name = name

pet = Dog('Milo')
print(pet.name)

class Counter:
    def __init__(self, start=0):
        self.value = start
    def increment(self):
        self.value += 1
counter = Counter(4)
counter.increment()
print(counter.value)
